HANDLERS["fusion sage"] = (game, gc, target) => {
    const r = p.searchDeckToHandByName(game, gc.owner, "Polymerization");
    if (r.found) { game.addLog(`${gc.owner.name} adds Polymerization to their hand with ${gc.card.name}!`); }
    else { game.addLog(`${gc.card.name} finds no copy of Polymerization in the Deck.`); }
};

